#include <iostream>
#include <ranges>

int main() {
    for (int year :
        std::views::iota(2020) | std::views::take_while([](int y) { return y < 2026; }))
        std::cout << year << ' ';
    std::cout << '\n';

    const char note[]{"Today is yesterday's tomorrow!..."};
    auto not_dot = [](char c) { return c != '.'; };
    for (char x : std::ranges::take_while_view(note, not_dot))
        std::cout << x;
    std::cout << '\n';
}
